    "desc": "ラインケアは、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「ラインケアは、管理監督者が日常の職場管理を通じて部下の変化に気づき、相談対応・職場環境改善・専門職への橋渡しを行うケアです」という出題上のポイントと結びつけて理解します。過去問・演習では「管理監督者は抱え込まず、専門家や産業保健スタッフと連携することが重要」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、ストレス、産業医、事業場外資源によるケア、職場環境の改善もあわせて確認すると理解がつながります。\n\nラインケアは、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「ラインケアは、管理監督者が日常の職場管理を通じて部下の変化に気づき、相談対応・職場環境改善・専門職への橋渡しを行うケアです」という出題上のポイントと結びつけて理解します。過去問・演習では「管理監督者は抱え込まず、専門家や産業保健スタッフと連携することが重要」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、ストレス、産業医、事業場外資源によるケア、職場環境の改善もあわせて確認すると理解がつながります。"
