    "desc": "事業場内産業保健スタッフ等によるケアは、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「4つのケア：①セルフケア（労働者自身）②ラインによるケア（管理監督者）③事業場内産業保健スタッフ等によるケア（産業医・保健師等）④事業場外資源によるケア（外部機関）」という出題上のポイントと結びつけて理解します。過去問・演習では「4つのケア：①セルフケア（労働者自身）②ラインによるケア（管理監督者）③事業場内産業保健スタッフ等によるケア（産業医・保健師等）④事業場外資源によるケア（外部機関）」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、事業場外資源によるケア、産業医、セルフケア、保健師もあわせて確認すると理解がつながります。\n\n事業場内産業保健スタッフ等によるケアは、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「4つのケア：①セルフケア（労働者自身）②ラインによるケア（管理監督者）③事業場内産業保健スタッフ等によるケア（産業医・保健師等）④事業場外資源によるケア（外部機関）」という出題上のポイントと結びつけて理解します。過去問・演習では「4つのケア：①セルフケア（労働者自身）②ラインによるケア（管理監督者）③事業場内産業保健スタッフ等によるケア（産業医・保健師等）④事業場外資源によるケア（外部機関）」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、事業場外資源によるケア、産業医、セルフケア、保健師もあわせて確認すると理解がつながります。"
