    "desc": "労働災害は、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「労働災害は、試験では「一般の労働者については、月80時間超の時間外・休日労働を行い疲労の蓄積が認められる者が申し出た場合に、医師による面接指導が義務となる」という文脈で確認される用語です」という出題上のポイントと結びつけて理解します。過去問・演習では「一般の労働者については、月80時間超の時間外・休日労働を行い疲労の蓄積が認められる者が申し出た場合に、医師による面接指導が義務となる」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、面接指導、長時間労働、業務起因性、過労死等防止対策推進法もあわせて確認すると理解がつながります。\n\n労働災害は、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「労働災害は、試験では「一般の労働者については、月80時間超の時間外・休日労働を行い疲労の蓄積が認められる者が申し出た場合に、医師による面接指導が義務となる」という文脈で確認される用語です」という出題上のポイントと結びつけて理解します。過去問・演習では「一般の労働者については、月80時間超の時間外・休日労働を行い疲労の蓄積が認められる者が申し出た場合に、医師による面接指導が義務となる」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、面接指導、長時間労働、業務起因性、過労死等防止対策推進法もあわせて確認すると理解がつながります。"
