    "desc": "安全衛生推進者は、職場での健康障害防止、労働時間管理、安全衛生体制、災害補償などと関係します。メンタルヘルス対策でも、長時間労働、ストレスチェック、面接指導、職場環境改善を制度面から支える基礎になります。職場では、用語の意味だけでなく、誰が対応し、どの情報を共有し、どの専門職につなぐかまで確認します。実務では、用語を単独で覚えるのではなく、ラインケア・安全配慮・専門職連携の流れに置いて確認します。\n\n安全衛生推進者は、職場での健康障害防止、労働時間管理、安全衛生体制、災害補償などと関係します。メンタルヘルス対策でも、長時間労働、ストレスチェック、面接指導、職場環境改善を制度面から支える基礎になります。職場では、用語の意味だけでなく、誰が対応し、どの情報を共有し、どの専門職につなぐかまで確認します。実務では、用語を単独で覚えるのではなく、ラインケア・安全配慮・専門職連携の流れに置いて確認します。"
