    "desc": "安全配慮義務は、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「安全配慮義務は、使用者が労働者の生命・身体等の安全を確保しつつ働けるよう必要な配慮をする義務です」という出題上のポイントと結びつけて理解します。過去問・演習では「安全配慮義務は労働契約法5条に規定され、身体的・精神的健康の両方に及ぶ」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、刑事罰、公法的規制、私法的規制、慰謝料もあわせて確認すると理解がつながります。\n\n安全配慮義務は、メンタルヘルスケアの意義、管理監督者の役割、ストレスや疾病の基礎理解に関わる用語です。まず「安全配慮義務は、使用者が労働者の生命・身体等の安全を確保しつつ働けるよう必要な配慮をする義務です」という出題上のポイントと結びつけて理解します。過去問・演習では「安全配慮義務は労働契約法5条に規定され、身体的・精神的健康の両方に及ぶ」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、管理監督者が医学的判断を抱え込まず、職場で観察できる事実と専門職への連携を分けて理解することが重要です。関連する用語として、刑事罰、公法的規制、私法的規制、慰謝料もあわせて確認すると理解がつながります。"
