    "desc": "職場復帰後のフォローアップは、相談対応、社内外資源との連携、休業者の職場復帰支援に関わる用語です。まず「科目: 心の健康問題をもつ復職者への支援の方法 主治医による職場復帰可能の診断書の提出 職場復帰の可否の判断および職場復帰支援プランの作成 最終的な職場復帰の決定 職場復帰後のフォローアップ」という出題上のポイントと結びつけて理解します。過去問・演習では「第1＝休業開始・休業中のケア、第2＝主治医による復帰可能の判断、第3＝復帰可否の判断とプラン作成、第4＝最終的な復帰決定、第5＝フォローアップ」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、本人の話を聴き、必要な範囲で産業保健スタッフや社外資源へつなぐことが重要です。関連する用語として、休業、最終的な職場復帰の決定、職場復帰支援プランの作成、主治医による職場復帰可能の判断もあわせて確認すると理解がつながります。\n\n職場復帰後のフォローアップは、相談対応、社内外資源との連携、休業者の職場復帰支援に関わる用語です。まず「科目: 心の健康問題をもつ復職者への支援の方法 主治医による職場復帰可能の診断書の提出 職場復帰の可否の判断および職場復帰支援プランの作成 最終的な職場復帰の決定 職場復帰後のフォローアップ」という出題上のポイントと結びつけて理解します。過去問・演習では「第1＝休業開始・休業中のケア、第2＝主治医による復帰可能の判断、第3＝復帰可否の判断とプラン作成、第4＝最終的な復帰決定、第5＝フォローアップ」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、本人の話を聴き、必要な範囲で産業保健スタッフや社外資源へつなぐことが重要です。関連する用語として、休業、最終的な職場復帰の決定、職場復帰支援プランの作成、主治医による職場復帰可能の判断もあわせて確認すると理解がつながります。"
